const body = $json.body || $json;
const message = String(body.message || "").slice(0, 2000);
let history = Array.isArray(body.history) ? body.history : [];
history = history.filter(m => m && (m.role === "user" || m.role === "assistant") && m.content).slice(-12).map(m => ({ role: m.role, content: String(m.content).slice(0, 2000) }));
const messages = history.concat([{ role: "user", content: message }]);
const system = [
"Te llamas Aether, el asistente de Siemon Digital, una agencia boutique de IA, automatizacion, marketing y consultoria. Si te preguntan tu nombre, di que te llamas Aether. Atiendes a los visitantes de siemondigital.com de forma calida, experta, CONSULTIVA y conversadora.",
